	// Wealth Simple has a fixed positional layout; data always starts after the
	// header row. The shared `parse()` template supplies the try/catch that this
	// parser previously lacked.
	protected resolveLayout(): CSVLayout {
		return { dataStartIndex: 1 };
	}

	// #{#wsp2b} Transaction parsing.
	// Note the row-level order differs from the other banks (date → details →
	// amount) and the messages/sign rules are Wealth-Simple-specific, so this hook
	// does not use the shared `finalizeRow` helper.
	protected parseRow(
		row: string[],
		_layout: CSVLayout,
		rowIndex: number,
		errors: string[]
	): ParsedTransaction | null {
		const rowNumber = rowIndex + 1;

		// Skip empty rows
		if (!row || row.every((cell) => !cell?.trim())) {
			return null;
		}

		// Validate row has enough columns (at least 5 for the data we need)
		if (row.length < 5) {
			errors.push(`Row ${rowNumber}: Incomplete row (expected 6 columns, got ${row.length})`);
			return null;
		}

		// Parse transaction_date (YYYY-MM-DD format) from column 0
		const dateStr = row[0]?.trim();
		const transactionDate = this.parseDate(dateStr);
		if (!transactionDate) {
			errors.push(`Row ${rowNumber}: Invalid transaction_date "${dateStr}"`);
			return null;
		}

		// Parse vendor_name from details column (column 3)
		const vendorName = row[3]?.trim();
		if (!vendorName) {
			errors.push(`Row ${rowNumber}: Missing details/vendor name`);
			return null;
		}

		// Parse type from column 2 (Purchase, Payment, Refund initiated, Refund settled)
		const txnType = row[2]?.trim().toLowerCase() || '';

		// Parse amount from column 4
		const amountStr = row[4]?.trim();
		const rawAmount = this.parseAmount(amountStr);
		if (rawAmount === null) {
			errors.push(`Row ${rowNumber}: Invalid amount "${amountStr}"`);
			return null;
		}

		// Wealth Simple CSV exports use inconsistent signs across downloads.
		// Use the type column to enforce correct sign: (#{#wsp1a})
		//   Purchase → negative (expense)
		//   Payment, Refund → positive (credit)
		const absAmount = Math.abs(rawAmount);
		const normalizedAmount = absAmount === 0 ? 0 : txnType === 'purchase' ? -absAmount : absAmount;

		return {
			transaction_date: transactionDate,
			vendor_name: vendorName,
			amount: normalizedAmount
		};
	}
}

